package dev.industrialtechnology.client;
import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.EntityRenderer;import dev.industrialtechnology.railway.EntityRollingStock;import cpw.mods.fml.common.eventhandler.SubscribeEvent;import cpw.mods.fml.common.gameevent.TickEvent;import cpw.mods.fml.relauncher.ReflectionHelper;import java.lang.reflect.Field;
/** Extend vanilla's collision-clipped third-person camera beyond the long locomotive body. */
public final class RailCamera {
 private final Field distance=ReflectionHelper.findField(EntityRenderer.class,"thirdPersonDistance","field_78490_B"),previous=ReflectionHelper.findField(EntityRenderer.class,"thirdPersonDistanceTemp","field_78491_C");private boolean changed;private float saved,savedPrevious,current;
 @SubscribeEvent public void render(TickEvent.RenderTickEvent e){if(e.phase!=TickEvent.Phase.START)return;Minecraft mc=Minecraft.getMinecraft();boolean riding=mc.thePlayer!=null&&mc.thePlayer.ridingEntity instanceof EntityRollingStock&&mc.gameSettings.thirdPersonView>0;try{if(riding){if(!changed){saved=distance.getFloat(mc.entityRenderer);savedPrevious=previous.getFloat(mc.entityRenderer);current=saved;changed=true;}EntityRollingStock stock=(EntityRollingStock)mc.thePlayer.ridingEntity;float target=(float)(stock.stock.length*.85+6);current+=(target-current)*.15f;distance.setFloat(mc.entityRenderer,current);previous.setFloat(mc.entityRenderer,current);}else if(changed){distance.setFloat(mc.entityRenderer,saved);previous.setFloat(mc.entityRenderer,savedPrevious);changed=false;}}catch(IllegalAccessException ex){throw new IllegalStateException("Rail camera fields",ex);}}
}
